/**
 * FrameBrandGlyph — the Frame mark (#1872 rebrand, replaces
 * YouTubeBrandGlyph). Original geometry: a perforated film cell with a play
 * triangle — a "frame of film" motif, inheriting `currentColor`. Decorative
 * by default (`aria-hidden`): the consuming surface carries the accessible
 * name (e.g. a pill label). Brand marks are never mirrored in RTL, mirroring
 * KiteBrandGlyph's shape exactly.
 *
 * Verbatim geometry copy of
 * frontends/range-mfe/src/components/content/FrameBrandGlyph.tsx — packages
 * cannot import across, so frame-mfe carries its own copy (icon-guardrail.sh
 * SVG_ALLOWLIST carries a matching row for this file). Two deltas from the
 * range-mfe source: `focusable="false"` is added, and `className` has no
 * default value (a default would add a branch to an otherwise
 * coverage-free file).
 */

import { type ReactElement } from "react";

export function FrameBrandGlyph({
  className,
}: {
  readonly className?: string;
}): ReactElement {
  return (
    <svg
      viewBox="0 0 32 32"
      fill="none"
      stroke="currentColor"
      aria-hidden="true"
      focusable="false"
      className={className}
    >
      <rect x="4" y="6" width="24" height="20" rx="3.5" strokeWidth="2.4" />
      <path d="M9 6 V26 M23 6 V26" strokeWidth="1.5" opacity="0.45" />
      <path d="M14 12.5 L20.5 16 L14 19.5 Z" fill="currentColor" />
    </svg>
  );
}


--- frontends/frame-mfe/src/components/FrameChannelAvatar.tsx (95 lines) ---
/**
 * FrameChannelAvatar — the small round channel avatar on a video card
 * (DESIGN.md §3; #2953).
 *
 * Deliberately NOT `platform-chrome`'s `KiteAvatar`: that component is
 * Kite-flavoured (its style resolves from `KiteAvatarStyleContext`, a
 * Kite-specific provider frame-mfe does not mount), and reusing it directly
 * would either crash with no provider or silently couple Frame's own
 * channel avatars to Kite's exercise-wide style choice. This component
 * instead composes the same UNDERLYING, generic, non-Kite-specific
 * pipeline `KiteAvatar` itself is built on — `createAvatarDataUri`
 * (`@omnicore-platform/platform-chrome/avatar`, a synchronous, offline,
 * air-gap-safe `data:image/svg+xml` render, no network call) and
 * `getMonogramChar`/`getMonogramColor` (`@omnicore-platform/platform-chrome`,
 * the same monogram helpers the topbar/user-menu already use) — so the
 * seed-hashed palette and DiceBear pipeline still live in exactly one
 * place, without leaking a `kite-*`-scoped dependency into this package.
 *
 * An empty `avatarSeed` renders the monogram fallback per DESIGN.md's "What
 * to build": initial from `channelName`, deterministic color from
 * `channelName` (there is no separate stable id to hash on here, unlike
 * KiteAvatar's `monogramSeed` — a channel's own display name is already
 * stable across renders for the fixtures this package ships).
 *
 * Decorative: the adjacent channel-name text (rendered by the caller)
 * carries the accessible identity, so the DiceBear `<img>` gets `alt=""`
 * and the monogram `<span>` gets `aria-hidden="true"`.
 *
 * `text-white` on the monogram fallback is a literal, not a `frame-*`/
 * `cog-*` token — a deliberate, pre-existing exception for this one
 * hash-driven palette, not a violation of the "every colour is a declared
 * token" rule: `getMonogramColor`'s five-color palette (`monogram.ts`) is
 * itself already chosen dark enough that white text clears 4.5:1 against
 * every entry, and `platform-chrome/src/Topbar.tsx:648-652` pairs the exact
 * same helper pair with the exact same `text-white` for its user-menu
 * trigger — a per-seed hash cannot be a fixed design token by construction,
 * so this mirrors the one other shipped consumer of this palette rather
 * than inventing a new rule.
 */
import { type ReactElement, useMemo } from "react";
import {
  createAvatarDataUri,
  DEFAULT_AVATAR_STYLE,
} from "@omnicore-platform/platform-chrome/avatar";
import { getMonogramChar, getMonogramColor } from "@omnicore-platform/platform-chrome";

export interface FrameChannelAvatarProps {
  readonly channelName: string;
  /** DiceBear render seed. "" renders the monogram fallback. */
  readonly avatarSeed: string;
  /** Diameter in px. */
  readonly size?: number;
}

export function FrameChannelAvatar({
  channelName,
  avatarSeed,
  size = 36,
}: FrameChannelAvatarProps): ReactElement {
  const dataUri = useMemo(
    () =>
      avatarSeed === ""
        ? ""
        : createAvatarDataUri(avatarSeed, DEFAULT_AVATAR_STYLE, { size }),
    [avatarSeed, size],
  );

  if (avatarSeed === "") {
    return (
      <span
        aria-hidden="true"
        className="inline-flex shrink-0 items-center justify-center rounded-pill font-semibold text-white"
        style={{
          width: size,
          height: size,
          fontSize: Math.round(size * 0.42),
          backgroundColor: getMonogramColor(channelName),
        }}
      >
        {getMonogramChar(channelName)}
      </span>
    );
  }

  return (
    <img
      src={dataUri}
      alt=""
      width={size}
      height={size}
      className="shrink-0 rounded-pill"
    />
  );
}


--- frontends/frame-mfe/src/components/FrameLayout.tsx (76 lines) ---
/**
 * FrameLayout — the shared page shell wrapping FrameTopBar, an optional
 * back link, and <main> (DESIGN.md §3, §9; PLAN.md Task 5).
 *
 * `<section aria-label={m.frame_app_name()}>` is what names the embedded
 * region — deliberately no explicit banner role anywhere in this tree (see
 * FrameTopBar.tsx): range-mfe's own chrome shell already contributes a
 * banner landmark when Frame is embedded.
 *
 * The back link mirrors Commons' `BackToCommunities` shape
 * (frontends/commons-mfe/src/CommonsApp.tsx:166-176): a single `Link` to a
 * caller-supplied href, rendering `← {frame_browse_heading}`. Unlike
 * BackToCommunities (always rendered by its caller only in embedded
 * routes), FrameLayout exposes that choice as its own optional `backHref`
 * prop: supplying it renders the link (its href is the basePath when
 * embedded, the standalone root when not — the caller, e.g. a future
 * WatchRoute, resolves which and passes the resolved string here); omitting
 * it renders no back link at all (e.g. BrowseRoute, which has no "back"
 * target of its own).
 *
 * `exerciseId` (#2872) — threaded straight through to FrameTopBar, whose
 * login modal needs it for the POST /api/v1/frame/login body. Optional,
 * defaulting to "": the login affordance renders in FrameTopBar on every
 * route (Browse, Watch, and the Stub screens), so every caller of
 * FrameLayout forwards its own resolved exercise id — BrowseRoute/WatchRoute/
 * StubRoute all accept an `exerciseId` prop and FrameApp.tsx's standalone and
 * embedded route wiring supplies it (from the `:exercise` URL segment or the
 * `exerciseId` prop respectively) so a participant can log in from wherever
 * they clicked the affordance, not just the browse grid.
 */

import { type ReactElement, type ReactNode } from "react";
import { Link } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { FrameTopBar } from "./FrameTopBar";
import { FOCUS_RING } from "../lib/frameClasses";

export interface FrameLayoutProps {
  /** Href for FrameTopBar's brand link home. */
  readonly homeHref: string;
  /** When supplied, renders the "← Videos" back link at this href. Omit to
   * render no back link. */
  readonly backHref?: string;
  /** The exercise FrameTopBar's login modal should authenticate against.
   * Optional — see this file's header note. */
  readonly exerciseId?: string;
  readonly children: ReactNode;
}

export function FrameLayout({
  homeHref,
  backHref,
  exerciseId = "",
  children,
}: FrameLayoutProps): ReactElement {
  return (
    <section
      aria-label={m.frame_app_name()}
      className="min-h-full bg-frame-bg text-frame-text"
    >
      <FrameTopBar homeHref={homeHref} exerciseId={exerciseId} />
      {backHref !== undefined && (
        <div className="px-cog-5 pt-cog-4">
          <Link
            to={backHref}
            className={`text-body-sm font-semibold text-frame-accent hover:underline ${FOCUS_RING}`}
          >
            ← {m.frame_browse_heading()}
          </Link>
        </div>
      )}
      <main>{children}</main>
    </section>
  );
}


--- frontends/frame-mfe/src/components/FrameLoginModal.tsx (202 lines) ---
/**
 * FrameLoginModal — the Frame participant login dialog: handle + password
 * only, no profile picker (#2872 — the ticket explicitly scopes out Kite's
 * searchable-list complexity for Frame).
 *
 * Structural precedent:
 * frontends/range-mfe/src/components/kite/KiteProfileLoginModal.tsx,
 * simplified. Kept verbatim: the brand-glyph + title + close-button header,
 * the description paragraph, the labeled handle/password inputs
 * (`autoComplete="username"`/`"current-password"`), the in-flight submit
 * button (`aria-busy`, disabled while submitting), and the non-disclosing
 * error path — a non-ok response and a thrown network error both hit the
 * identical generic branch (src/api/frame.ts's `FrameLoginError` collapses
 * both causes into one type specifically so this component never has to tell
 * them apart, and never reads a failure response body). Dropped entirely:
 * the `useProfiles`/search/debounce machinery and the profile quick-select
 * list — Frame's ticket only calls for a manual handle+password form.
 *
 * The dialog SHELL is no longer hand-rolled. It is `@omnicore-platform/ui`'s
 * `Dialog` (Radix), which owns the scrim, the portal, the `role="dialog"`
 * node, the focus trap, Escape/outside-pointerdown dismissal, and the
 * accessible name/description wiring off `Dialog.Title`/`Dialog.Description`
 * — so the old `useId()` pair for `aria-labelledby`/`aria-describedby`, the
 * hand-written scrim `<div>`, and the `if (!isOpen) return null` early-out
 * are all gone. Consequence worth knowing: unlike the Kite precedent (and
 * unlike this file before the migration), Escape and a backdrop click now DO
 * dismiss — that is Radix's built-in behavior, routed to `onClose` through
 * `onOpenChange`, and re-implementing a suppression on top of the primitive
 * is exactly what the shared Dialog exists to prevent.
 *
 * The Frame look is preserved by overriding the primitive's cog chrome at
 * the call site with this package's own `frame-*` tokens (`size="wide"` is
 * used ONLY for its vertical centering — the width is overridden right back
 * to the original `w-full max-w-md`).
 *
 * One deliberate shape deviation from Kite's `onLoginSuccess: () => void`:
 * this modal's `onLoginSuccess` carries the resolved `FrameSession`.
 * FrameTopBar (the mount point) needs the identity to render immediately
 * without a second read — see useFrameSession.ts's own note on why the
 * module cache alone doesn't push a live update to an already-mounted hook
 * instance. `setFrameSession` is still called first (seeding the cache for
 * any OTHER, not-yet-mounted, consumer), exactly as Commons' login flow
 * does.
 */
import { type FormEvent, type ReactElement, useId, useState } from "react";
import { Dialog } from "@omnicore-platform/ui";
import { X } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useToast } from "@omnicore-platform/platform-chrome/toast";
import { FrameBrandGlyph } from "./FrameBrandGlyph";
import { FOCUS_RING } from "../lib/frameClasses";
import { login, type FrameSession } from "../api/frame";
import { setFrameSession } from "../hooks/useFrameSession";

export interface FrameLoginModalProps {
  /** Whether the overlay dialog is open. */
  readonly isOpen: boolean;
  /** Exercise whose /api/v1/frame/login endpoint this modal targets. */
  readonly exerciseId: string;
  /** Close request (close button, Escape, or an outside click). */
  readonly onClose: () => void;
  /** Fired after a successful login, with the resolved session. */
  readonly onLoginSuccess: (session: FrameSession) => void;
}

const INPUT_CLASSES =
  "min-h-input w-full rounded-xl border border-frame-border-strong bg-frame-bg ps-cog-4 pe-cog-4 text-frame-text";
const LABEL_CLASSES = "text-body-sm font-medium text-frame-text2";

export function FrameLoginModal({
  isOpen,
  exerciseId,
  onClose,
  onLoginSuccess,
}: FrameLoginModalProps): ReactElement {
  const handleId = useId();
  const passwordId = useId();
  const toast = useToast();

  const [handleValue, setHandleValue] = useState("");
  const [passwordValue, setPasswordValue] = useState("");
  const [submitting, setSubmitting] = useState(false);

  // Submit the credentials to the participant /frame login endpoint. On
  // success the cache is seeded and the caller notified with the session so
  // the chrome can render it immediately. On failure (a non-ok response OR
  // a thrown network error — login() collapses both into FrameLoginError)
  // the password is cleared for retry (handle stays) and a localized,
  // non-disclosing error surfaces via the shared danger toast — the backend
  // deliberately never says whether the handle or the password was wrong,
  // so this modal can't either.
  async function handleSubmit(e: FormEvent): Promise<void> {
    e.preventDefault();
    setSubmitting(true);
    try {
      const session = await login(exerciseId, handleValue, passwordValue);
      setFrameSession(session);
      onLoginSuccess(session);
    } catch {
      setPasswordValue("");
      toast.danger(m.frame_login_error());
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Dialog.Root
      open={isOpen}
      onOpenChange={(next) => {
        if (!next) onClose();
      }}
    >
      {/* `size="wide"` supplies the ORIGINAL vertical centering (top-1/2 +
          -translate-y-1/2); its 960 px width is immediately overridden back
          to the pre-migration `w-full max-w-md`. The scrim keeps its
          original black/50 wash in BOTH themes — the shared cog scrim would
          be a visual change, and this is a primitive swap, not a restyle.
          `aria-modal` is set explicitly because Radix relies on its focus
          trap + outside-aria-hidden rather than the attribute. */}
      <Dialog.Content
        size="wide"
        aria-modal="true"
        overlayClassName="bg-black/50 dark:bg-black/50"
        className="w-full max-w-md rounded-xl border border-frame-border bg-frame-bg text-frame-text shadow-cog-e5"
      >
        {/* Header: brand mark + title + close. FrameBrandGlyph is
            aria-hidden by default — the Dialog.Title (an h2) carries the
            accessible name, and Radix wires aria-labelledby to it. */}
        <div className="flex items-center justify-between border-b border-frame-border p-cog-5">
          <div className="flex items-center gap-cog-3">
            <FrameBrandGlyph className="h-cog-5 w-cog-5 text-frame-accent" />
            <Dialog.Title className="text-heading-sm font-semibold text-frame-text">
              {m.frame_login_modal_title()}
            </Dialog.Title>
          </div>
          <button
            type="button"
            aria-label={m.frame_login_close()}
