import { useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactElement } from "react";
import { useLocaleDirection } from "@omnicore-platform/platform-chrome";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { ChevronLeft, ChevronRight } from "@omnicore-platform/ui/icons";
import { FRAME_CATEGORIES, type FrameCategory } from "../fixtures/categories";
import { FOCUS_RING } from "../lib/frameClasses";

/**
 * CategoryRail — the real, multi-chip category filter (#2955; DESIGN.md §3,
 * §9). Extends #2871's one-chip "All" rail into the full fixture set
 * (`src/fixtures/categories.ts`), a horizontally-scrolling `role="group"`
 * with a single-select `aria-pressed` chip per category, overflow arrows,
 * and roving-tabindex keyboard navigation. Renders entirely from the
 * `categories` prop/its fixture default — no fetch, ever
 * (`tests/tokens/*` and this file itself issue no network call).
 *
 * Controlled, not stateful: `selectedId`/`onSelect` are owned by the
 * caller (`BrowseRoute`, which mirrors selection into `?category=` — see
 * that file), the same Strategy-prop shape `BrowseRoute` already uses for
 * `loadVideos`. `CategoryRail` itself holds only UI-local state: which chip
 * is scrolled into/out of view.
 *
 * Roving tabindex is tied to `selectedId` (not a separately-tracked "last
 * focused" id): the SELECTED chip is the only one with `tabIndex={0}`, and
 * arrow-key navigation moves DOM focus directly via refs without touching
 * component state, so Tab-ing away and back always lands on the selected
 * chip. This is the WAI-ARIA APG "Tabs, automatic activation" shape, and it
 * means Enter/Space need no custom handling at all: every chip is a native
 * `<button>`, so activating a focused one already fires `onClick` — the
 * browser's own semantics, not a keydown reimplementation of them.
 *
 * Overflow detection deliberately reads only the FIRST and LAST chip's
 * `getBoundingClientRect()` against the scroller's own rect, never
 * `scrollLeft`. `scrollLeft`'s sign/range convention for a `dir="rtl"`
 * scroller is famously inconsistent across browsers (three different
 * conventions in the wild); a chip's rect is not — "is the first chip's box
 * fully inside the scroller's box" answers "can you scroll toward the
 * start" correctly regardless of which physical side "start" renders on.
 * This is also why the prev/next buttons are plain DOM siblings (before/
 * after the scroller) rather than absolutely positioned: normal flow plus
 * the ambient `dir` attribute already puts them on the correct physical
 * side with zero position math.
 *
 * DOM order, not physical position, defines "prev"/"next": the FIRST
 * category in the array is always what "prev" scrolls toward and the LAST
 * is always what "next" scrolls toward, in both directions — `dir` only
 * changes which side of the screen that motion appears to move toward,
 * which the browser's own `scrollIntoView`/arrow-icon-mirroring
 * (`rtl:-scale-x-100`, matching `ask-mfe/src/layout/AskLayout.tsx`'s
 * existing convention) already handles. `ArrowLeft`/`ArrowRight` swap which
 * DOM direction they move under RTL for the same reason PrimaryNavMenu.tsx
 * already swaps them (`useLocaleDirection()`, not a raw `document.dir`
 * read, so a locale switch inside a test needs only `setLocale(...)`).
 */

export interface CategoryRailProps {
  /** Defaults to the real fixture set (`FRAME_CATEGORIES`) — overridable so
   * tests/screenshots can exercise a guaranteed non-overflowing rail
   * (`FRAME_CATEGORIES_SHORT`) without depending on viewport width. */
  readonly categories?: readonly FrameCategory[];
  readonly selectedId: string;
  readonly onSelect: (id: string) => void;
}

// Tolerance for floating-point rect comparisons — real browsers can report
// sub-pixel rects that differ by a fraction of a px even when nothing is
// actually clipped.
const OVERFLOW_TOLERANCE_PX = 1;

const ARROW_BUTTON_CLASSES =
  "flex h-cog-6 w-cog-6 shrink-0 items-center justify-center rounded-pill border border-frame-border-strong bg-frame-surface text-frame-text2 hover:bg-frame-hover";

const CHIP_BASE_CLASSES = "shrink-0 rounded-pill px-cog-4 py-cog-2 text-body-sm";

const CHIP_SELECTED_CLASSES = "bg-frame-chip font-semibold text-frame-text";

// frame-accent is never text ink on frame-chip or frame-hover (4.22:1 /
// 4.24:1 light, both fail 4.5:1 — DESIGN.md §4 binding rule), so the
// unselected chip's label stays on frame-text2 (5.86:1 on frame-surface,
// 5.45:1 on frame-hover — both measured, both PASS) even on hover.
const CHIP_UNSELECTED_CLASSES =
  "border border-frame-border bg-frame-surface font-medium text-frame-text2 hover:bg-frame-hover";

function isFullyVisible(chipRect: DOMRect, scrollerRect: DOMRect): boolean {
  return (
    chipRect.left >= scrollerRect.left - OVERFLOW_TOLERANCE_PX &&
    chipRect.right <= scrollerRect.right + OVERFLOW_TOLERANCE_PX
  );
}

export default function CategoryRail({
  categories = FRAME_CATEGORIES,
  selectedId,
  onSelect,
}: CategoryRailProps): ReactElement {
  const dir = useLocaleDirection();
  const scrollerRef = useRef<HTMLDivElement | null>(null);
  const chipRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const [canScrollPrev, setCanScrollPrev] = useState(false);
  const [canScrollNext, setCanScrollNext] = useState(false);

  function recomputeOverflow(): void {
    const scroller = scrollerRef.current;
    const first = chipRefs.current[0];
    const last = chipRefs.current[chipRefs.current.length - 1];
    if (!scroller || !first || !last || chipRefs.current.length < 2) {
      setCanScrollPrev(false);
      setCanScrollNext(false);
      return;
    }
    const scrollerRect = scroller.getBoundingClientRect();
    setCanScrollPrev(!isFullyVisible(first.getBoundingClientRect(), scrollerRect));
    setCanScrollNext(!isFullyVisible(last.getBoundingClientRect(), scrollerRect));
  }

  useLayoutEffect(() => {
    recomputeOverflow();
    const scroller = scrollerRef.current;
    if (!scroller) return undefined;

    scroller.addEventListener("scroll", recomputeOverflow);
    window.addEventListener("resize", recomputeOverflow);

    // Real browsers only — jsdom's stub never invokes the callback, so tests
    // drive recomputation via the scroll listener above instead.
    const resizeObserver =
      typeof ResizeObserver === "undefined" ? undefined : new ResizeObserver(recomputeOverflow);
    resizeObserver?.observe(scroller);

    return () => {
      scroller.removeEventListener("scroll", recomputeOverflow);
      window.removeEventListener("resize", recomputeOverflow);
      resizeObserver?.disconnect();
    };
    // selectedId is a real dependency, not just categories: CHIP_SELECTED_CLASSES
    // (font-semibold) vs CHIP_UNSELECTED_CLASSES (font-medium) changes the
    // selected chip's rendered width, which can change scrollWidth without
    // resizing the scroller element itself — the ResizeObserver above watches
    // the scroller's own border-box, not this content-width change, so
    // selection changes need their own recompute trigger here.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [categories, selectedId]);

  function focusChipAt(index: number): void {
    const clamped = Math.max(0, Math.min(index, categories.length - 1));
    const chip = chipRefs.current[clamped];
    chip?.focus();
    chip?.scrollIntoView({ inline: "nearest", block: "nearest", behavior: "smooth" });
  }

  function handleChipKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number): void {
    // See the file header: DOM order defines "prev"/"next", and Arrow keys
    // swap which physical direction they move under RTL (mirrors
    // PrimaryNavMenu.tsx's identical `dir`-based swap).
    const forwardKey = dir === "rtl" ? "ArrowLeft" : "ArrowRight";
    const backwardKey = dir === "rtl" ? "ArrowRight" : "ArrowLeft";

    const target =
      event.key === forwardKey
        ? index + 1
        : event.key === backwardKey
          ? index - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? categories.length - 1
              : undefined;

    if (target === undefined) return;
    event.preventDefault();
    focusChipAt(target);
  }

  function scrollToEdge(edge: "start" | "end"): void {
    const index = edge === "start" ? 0 : categories.length - 1;
    chipRefs.current[index]?.scrollIntoView({
      inline: edge,
      block: "nearest",
      behavior: "smooth",
    });
  }

  return (
    <div
      role="group"
      aria-label={m.frame_category_rail_label()}
      className="flex min-w-cog-0 items-center gap-cog-2"
    >
      {canScrollPrev && (
        <button
          type="button"
          aria-label={m.frame_category_rail_scroll_prev()}
          onClick={() => scrollToEdge("start")}
          className={`${ARROW_BUTTON_CLASSES} ${FOCUS_RING}`}
        >
          <ChevronLeft aria-hidden="true" className="h-cog-4 w-cog-4 rtl:-scale-x-100" />
        </button>
      )}
      <div
        ref={scrollerRef}
        data-testid="frame-category-rail-scroller"
        className="flex min-w-cog-0 flex-1 gap-cog-2 overflow-x-auto scroll-smooth [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {categories.map((category, index) => {
          const isSelected = category.id === selectedId;
          return (
            <button
              key={category.id}
              ref={(node) => {
                chipRefs.current[index] = node;
              }}
              type="button"
              aria-pressed={isSelected}
              tabIndex={isSelected ? 0 : -1}
              onClick={() => onSelect(category.id)}
              onKeyDown={(event) => handleChipKeyDown(event, index)}
              className={`${CHIP_BASE_CLASSES} ${
                isSelected ? CHIP_SELECTED_CLASSES : CHIP_UNSELECTED_CLASSES
              } ${FOCUS_RING}`}
            >
              {category.label()}
            </button>
          );
        })}
      </div>
      {canScrollNext && (
        <button
          type="button"
          aria-label={m.frame_category_rail_scroll_next()}
          onClick={() => scrollToEdge("end")}
          className={`${ARROW_BUTTON_CLASSES} ${FOCUS_RING}`}
        >
          <ChevronRight aria-hidden="true" className="h-cog-4 w-cog-4 rtl:-scale-x-100" />
        </button>
      )}
    </div>
  );
}


