/**
 * FrameChannelAvatar — the small round channel avatar on a video card
 * (DESIGN.md §3; #2953).
 *
 * Deliberately NOT `platform-chrome`'s `KiteAvatar`: that component is
 * Kite-flavoured (its style resolves from `KiteAvatarStyleContext`, a
 * Kite-specific provider frame-mfe does not mount), and reusing it directly
 * would either crash with no provider or silently couple Frame's own
 * channel avatars to Kite's exercise-wide style choice. This component
 * instead composes the same UNDERLYING, generic, non-Kite-specific
 * pipeline `KiteAvatar` itself is built on — `createAvatarDataUri`
 * (`@omnicore-platform/platform-chrome/avatar`, a synchronous, offline,
 * air-gap-safe `data:image/svg+xml` render, no network call) and
 * `getMonogramChar`/`getMonogramColor` (`@omnicore-platform/platform-chrome`,
 * the same monogram helpers the topbar/user-menu already use) — so the
 * seed-hashed palette and DiceBear pipeline still live in exactly one
 * place, without leaking a `kite-*`-scoped dependency into this package.
 *
 * An empty `avatarSeed` renders the monogram fallback per DESIGN.md's "What
 * to build": initial from `channelName`, deterministic color from
 * `channelName` (there is no separate stable id to hash on here, unlike
 * KiteAvatar's `monogramSeed` — a channel's own display name is already
 * stable across renders for the fixtures this package ships).
 *
 * Decorative: the adjacent channel-name text (rendered by the caller)
 * carries the accessible identity, so the DiceBear `<img>` gets `alt=""`
 * and the monogram `<span>` gets `aria-hidden="true"`.
 *
 * `text-white` on the monogram fallback is a literal, not a `frame-*`/
 * `cog-*` token — a deliberate, pre-existing exception for this one
 * hash-driven palette, not a violation of the "every colour is a declared
 * token" rule: `getMonogramColor`'s five-color palette (`monogram.ts`) is
 * itself already chosen dark enough that white text clears 4.5:1 against
 * every entry, and `platform-chrome/src/Topbar.tsx:648-652` pairs the exact
 * same helper pair with the exact same `text-white` for its user-menu
 * trigger — a per-seed hash cannot be a fixed design token by construction,
 * so this mirrors the one other shipped consumer of this palette rather
 * than inventing a new rule.
 */
import { type ReactElement, useMemo } from "react";
import {
  createAvatarDataUri,
  DEFAULT_AVATAR_STYLE,
} from "@omnicore-platform/platform-chrome/avatar";
import { getMonogramChar, getMonogramColor } from "@omnicore-platform/platform-chrome";

export interface FrameChannelAvatarProps {
  readonly channelName: string;
  /** DiceBear render seed. "" renders the monogram fallback. */
  readonly avatarSeed: string;
  /** Diameter in px. */
  readonly size?: number;
}

export function FrameChannelAvatar({
  channelName,
  avatarSeed,
  size = 36,
}: FrameChannelAvatarProps): ReactElement {
  const dataUri = useMemo(
    () =>
      avatarSeed === ""
        ? ""
        : createAvatarDataUri(avatarSeed, DEFAULT_AVATAR_STYLE, { size }),
    [avatarSeed, size],
  );

  if (avatarSeed === "") {
    return (
      <span
        aria-hidden="true"
        className="inline-flex shrink-0 items-center justify-center rounded-pill font-semibold text-white"
        style={{
          width: size,
          height: size,
          fontSize: Math.round(size * 0.42),
          backgroundColor: getMonogramColor(channelName),
        }}
      >
        {getMonogramChar(channelName)}
      </span>
    );
  }

  return (
    <img
      src={dataUri}
      alt=""
      width={size}
      height={size}
      className="shrink-0 rounded-pill"
    />
  );
}


