/**
 * FrameLoginModal — the Frame participant login dialog: handle + password
 * only, no profile picker (#2872 — the ticket explicitly scopes out Kite's
 * searchable-list complexity for Frame).
 *
 * Structural precedent:
 * frontends/range-mfe/src/components/kite/KiteProfileLoginModal.tsx,
 * simplified. Kept verbatim: the brand-glyph + title + close-button header,
 * the description paragraph, the labeled handle/password inputs
 * (`autoComplete="username"`/`"current-password"`), the in-flight submit
 * button (`aria-busy`, disabled while submitting), and the non-disclosing
 * error path — a non-ok response and a thrown network error both hit the
 * identical generic branch (src/api/frame.ts's `FrameLoginError` collapses
 * both causes into one type specifically so this component never has to tell
 * them apart, and never reads a failure response body). Dropped entirely:
 * the `useProfiles`/search/debounce machinery and the profile quick-select
 * list — Frame's ticket only calls for a manual handle+password form.
 *
 * The dialog SHELL is no longer hand-rolled. It is `@omnicore-platform/ui`'s
 * `Dialog` (Radix), which owns the scrim, the portal, the `role="dialog"`
 * node, the focus trap, Escape/outside-pointerdown dismissal, and the
 * accessible name/description wiring off `Dialog.Title`/`Dialog.Description`
 * — so the old `useId()` pair for `aria-labelledby`/`aria-describedby`, the
 * hand-written scrim `<div>`, and the `if (!isOpen) return null` early-out
 * are all gone. Consequence worth knowing: unlike the Kite precedent (and
 * unlike this file before the migration), Escape and a backdrop click now DO
 * dismiss — that is Radix's built-in behavior, routed to `onClose` through
 * `onOpenChange`, and re-implementing a suppression on top of the primitive
 * is exactly what the shared Dialog exists to prevent.
 *
 * The Frame look is preserved by overriding the primitive's cog chrome at
 * the call site with this package's own `frame-*` tokens (`size="wide"` is
 * used ONLY for its vertical centering — the width is overridden right back
 * to the original `w-full max-w-md`).
 *
 * One deliberate shape deviation from Kite's `onLoginSuccess: () => void`:
 * this modal's `onLoginSuccess` carries the resolved `FrameSession`.
 * FrameTopBar (the mount point) needs the identity to render immediately
 * without a second read — see useFrameSession.ts's own note on why the
 * module cache alone doesn't push a live update to an already-mounted hook
 * instance. `setFrameSession` is still called first (seeding the cache for
 * any OTHER, not-yet-mounted, consumer), exactly as Commons' login flow
 * does.
 */
import { type FormEvent, type ReactElement, useId, useState } from "react";
import { Dialog } from "@omnicore-platform/ui";
import { X } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useToast } from "@omnicore-platform/platform-chrome/toast";
import { FrameBrandGlyph } from "./FrameBrandGlyph";
import { FOCUS_RING } from "../lib/frameClasses";
import { login, type FrameSession } from "../api/frame";
import { setFrameSession } from "../hooks/useFrameSession";

export interface FrameLoginModalProps {
  /** Whether the overlay dialog is open. */
  readonly isOpen: boolean;
  /** Exercise whose /api/v1/frame/login endpoint this modal targets. */
  readonly exerciseId: string;
  /** Close request (close button, Escape, or an outside click). */
  readonly onClose: () => void;
  /** Fired after a successful login, with the resolved session. */
  readonly onLoginSuccess: (session: FrameSession) => void;
}

const INPUT_CLASSES =
  "min-h-input w-full rounded-xl border border-frame-border-strong bg-frame-bg ps-cog-4 pe-cog-4 text-frame-text";
const LABEL_CLASSES = "text-body-sm font-medium text-frame-text2";

export function FrameLoginModal({
  isOpen,
  exerciseId,
  onClose,
  onLoginSuccess,
}: FrameLoginModalProps): ReactElement {
  const handleId = useId();
  const passwordId = useId();
  const toast = useToast();

  const [handleValue, setHandleValue] = useState("");
  const [passwordValue, setPasswordValue] = useState("");
  const [submitting, setSubmitting] = useState(false);

  // Submit the credentials to the participant /frame login endpoint. On
  // success the cache is seeded and the caller notified with the session so
  // the chrome can render it immediately. On failure (a non-ok response OR
  // a thrown network error — login() collapses both into FrameLoginError)
  // the password is cleared for retry (handle stays) and a localized,
  // non-disclosing error surfaces via the shared danger toast — the backend
  // deliberately never says whether the handle or the password was wrong,
  // so this modal can't either.
  async function handleSubmit(e: FormEvent): Promise<void> {
    e.preventDefault();
    setSubmitting(true);
    try {
      const session = await login(exerciseId, handleValue, passwordValue);
      setFrameSession(session);
      onLoginSuccess(session);
    } catch {
      setPasswordValue("");
      toast.danger(m.frame_login_error());
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Dialog.Root
      open={isOpen}
      onOpenChange={(next) => {
        if (!next) onClose();
      }}
    >
      {/* `size="wide"` supplies the ORIGINAL vertical centering (top-1/2 +
          -translate-y-1/2); its 960 px width is immediately overridden back
          to the pre-migration `w-full max-w-md`. The scrim keeps its
          original black/50 wash in BOTH themes — the shared cog scrim would
          be a visual change, and this is a primitive swap, not a restyle.
          `aria-modal` is set explicitly because Radix relies on its focus
          trap + outside-aria-hidden rather than the attribute. */}
      <Dialog.Content
        size="wide"
        aria-modal="true"
        overlayClassName="bg-black/50 dark:bg-black/50"
        className="w-full max-w-md rounded-xl border border-frame-border bg-frame-bg text-frame-text shadow-cog-e5"
      >
        {/* Header: brand mark + title + close. FrameBrandGlyph is
            aria-hidden by default — the Dialog.Title (an h2) carries the
            accessible name, and Radix wires aria-labelledby to it. */}
        <div className="flex items-center justify-between border-b border-frame-border p-cog-5">
          <div className="flex items-center gap-cog-3">
            <FrameBrandGlyph className="h-cog-5 w-cog-5 text-frame-accent" />
            <Dialog.Title className="text-heading-sm font-semibold text-frame-text">
              {m.frame_login_modal_title()}
            </Dialog.Title>
          </div>
          <button
            type="button"
            aria-label={m.frame_login_close()}
            onClick={onClose}
            className={`rounded-pill p-cog-1 text-frame-text2 hover:bg-frame-hover hover:text-frame-text ${FOCUS_RING}`}
          >
            {/* Decorative — the button's aria-label is the accessible name. */}
            <X className="h-cog-4-5 w-cog-4-5" aria-hidden="true" focusable="false" />
          </button>
        </div>

        <div className="p-cog-5">
          <Dialog.Description className="mb-cog-5 text-body-sm text-frame-text2">
            {m.frame_login_description()}
          </Dialog.Description>

          <form
            className="flex flex-col gap-cog-4"
            aria-busy={submitting}
            onSubmit={(e) => {
              void handleSubmit(e);
            }}
          >
            <div className="flex flex-col gap-cog-1">
              <label htmlFor={handleId} className={LABEL_CLASSES}>
                {m.frame_login_handle_label()}
              </label>
              <input
                id={handleId}
                type="text"
                autoComplete="username"
                value={handleValue}
                onChange={(e) => setHandleValue(e.target.value)}
                className={`${INPUT_CLASSES} ${FOCUS_RING}`}
              />
            </div>
            <div className="flex flex-col gap-cog-1">
              <label htmlFor={passwordId} className={LABEL_CLASSES}>
                {m.frame_login_password_label()}
              </label>
              <input
                id={passwordId}
                type="password"
                autoComplete="current-password"
                value={passwordValue}
                onChange={(e) => setPasswordValue(e.target.value)}
                className={`${INPUT_CLASSES} ${FOCUS_RING}`}
              />
            </div>
            <button
              type="submit"
              disabled={submitting}
              aria-busy={submitting}
              className={`flex min-h-btn w-full items-center justify-center gap-cog-2 rounded-pill border border-transparent bg-frame-accent-solid px-cog-5 font-semibold text-frame-accent-ink disabled:cursor-not-allowed disabled:border-frame-border disabled:bg-frame-hover disabled:text-frame-text2 disabled:opacity-50 ${FOCUS_RING}`}
            >
              {submitting ? m.frame_login_authenticating() : m.frame_login_submit()}
            </button>
          </form>
        </div>
      </Dialog.Content>
    </Dialog.Root>
  );
}

export default FrameLoginModal;


