/**
 * FrameThumb — the video-grid/rail thumbnail aspect-ratio box (DESIGN.md
 * §6, §7). Unlike FramePlayer, this ground correctly flips with theme
 * (bg-cog-surface-muted) — only the player is theme-invariant.
 *
 * `src` is optional. Absent (always true in #2871 — `listVideos()` resolves
 * to `[]`): the box is permanently filled by the shared shimmer Skeleton,
 * the wrapper carries `aria-busy="true"`, and no `<img>` renders at all —
 * rendering a hidden `<img>` here would make the errored branch below
 * unreachable and uncovered. Present: a three-state `<img>` lifecycle
 * (idle → loaded | errored), following the three-state image idiom at
 * frontends/studio-mfe/src/components/PropagandaLibraryModal.tsx:414-440 —
 * the Skeleton still covers the box while idle, then the image alone
 * remains once loaded; on error the box stays mounted and a fallback
 * renders in place of the image.
 */

import { useState, type ReactElement } from "react";
import { Skeleton } from "@omnicore-platform/ui";

type ThumbState = "idle" | "loaded" | "errored";

export interface FrameThumbProps {
  readonly src?: string;
  readonly durationLabel?: string;
}

export function FrameThumb({ src, durationLabel }: FrameThumbProps): ReactElement {
  const [state, setState] = useState<ThumbState>("idle");
  const busy = state === "idle";

  return (
    <div
      className="relative aspect-video w-full overflow-hidden rounded-md bg-cog-surface-muted"
      aria-busy={busy}
    >
      {busy && (
        <Skeleton className="absolute inset-cog-0 h-full w-full rounded-none" />
      )}
      {src !== undefined && state !== "errored" && (
        <img
          src={src}
          alt=""
          width={320}
          height={180}
          loading="lazy"
          decoding="async"
          onLoad={() => setState("loaded")}
          onError={() => setState("errored")}
          className={`absolute inset-cog-0 h-full w-full object-cover transition-opacity duration-standard ${
            state === "loaded" ? "opacity-100" : "opacity-0"
          }`}
        />
      )}
      {state === "errored" && (
        <div
          aria-hidden="true"
          data-testid="frame-thumb-fallback"
          className="absolute inset-cog-0"
        />
      )}
      {durationLabel !== undefined && (
        <span className="absolute end-cog-1 bottom-cog-1 rounded-sm bg-black/80 px-cog-1 text-caption tabular-nums text-white">
          {durationLabel}
        </span>
      )}
    </div>
  );
}


