/**
 * FrameTopBar — the plain <header> chrome above browse/watch (DESIGN.md §3,
 * §9; PLAN.md Task 5; login/logout affordance added #2872).
 *
 * Deliberately no explicit banner role: embedded Frame renders inside
 * range-mfe's own browser-chrome shell, which already contributes its own
 * banner landmark. A second `banner` here would be a duplicate landmark,
 * not a correction — tests/components/FrameTopBar.test.tsx asserts
 * `queryAllByRole("banner")` is empty.
 *
 * Search field: `frame_search_label` is the input's accessible NAME (an
 * `sr-only <label htmlFor>`), never the placeholder — a placeholder is not
 * an accessible name (design.md's form-field rule). `frame_search_placeholder`
 * supplies distinct visible hint copy. The field is non-functional in this
 * slice (#2871): no search route, no query state, no submit handler — it is
 * chrome only, wired up once a real search surface exists.
 *
 * The input's boundary is `border-frame-border-strong`, NOT `border-frame-
 * border`: `frame-border` measures 1.17-1.28:1 in both themes (correct for
 * a decorative hairline, wrong here) while design.md:33 requires an idle
 * input boundary >= 3:1; `frame-border-strong` clears that bar (3.55:1
 * light / 4.04:1 dark). DESIGN.md §4 records the split — do not simplify
 * these to one token.
 *
 * No explicit `role` on the `<header>`, and deliberately no `role="banner"`.
 * Per the ARIA-in-HTML mapping table a `<header>` scoped to a
 * sectioning-content ancestor — the `<section>` FrameLayout wraps it in —
 * computes to the generic role in a real browser, NOT "banner", so no
 * duplicate landmark reaches AT: range-mfe's own chrome already owns the
 * page's banner when Frame is embedded.
 *
 * Do NOT add a role here to satisfy a test. `@testing-library/dom`'s
 * implicit-role computation (`aria-query`'s `elementRoles` map) ignores that
 * map's `constraints` field, so under jsdom a bare `<header>` reports
 * "banner" regardless of ancestor. That is a tooling limitation, not real
 * behavior, and pinning an author role to work around it would change the
 * semantics real users get. The test asserts the honest invariant instead:
 * this component sets no role of its own, and FrameLayout provides the
 * sectioning ancestor that suppresses the banner mapping.
 *
 * ─── Login/logout affordance (#2872) ────────────────────────────────────
 *
 * DESIGN.md's two-trust-zone model: reads never need a `frame_session`;
 * only ACTING as a character does. With no acting profile the chrome shows
 * a Log in button where the (not-yet-built) authoring entry point would
 * sit; with one, it shows the character's identity + a Log out button.
 * `KiteApp.tsx`'s `activeCharacterId === null ? <Login/> : <Logout+.../>`
 * branch is the precedent shape, adapted to a single top-bar row (Frame has
 * no left nav rail). "loading" renders identically to "unauthenticated" —
 * never flash an authoring affordance during that tick (there is no
 * authoring affordance in this slice at all, so this mostly matters for not
 * flashing the identity chip before a session is confirmed).
 *
 * This component owns BOTH the login modal's open/close state AND the
 * session it displays, rather than splitting that across FrameLayout (as
 * the ticket's own "one reasonable shape" suggested). Reason: useFrameSession
 * ()'s module cache has no live-update path back to an already-mounted hook
 * instance (see that hook's own doc comment) — the instant this component's
 * OWN login/logout action changes the session, it needs to reflect that
 * without remounting. Keeping the modal + a small local `override` state
 * here, rather than in FrameLayout, avoids threading that override back
 * down through another prop layer for no benefit — FrameLayout would have
 * had to own state it never renders anything from.
 */

import { type ReactElement, useId, useState } from "react";
import { Link } from "react-router-dom";
import { Search } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { FrameBrandGlyph } from "./FrameBrandGlyph";
import { FrameLoginModal } from "./FrameLoginModal";
import { FOCUS_RING } from "../lib/frameClasses";
import { logout as apiLogout, type FrameSession } from "../api/frame";
import { clearFrameSession, useFrameSession } from "../hooks/useFrameSession";

export interface FrameTopBarProps {
  /** Href for the brand-mark link home (basePath when embedded, the
   * standalone root when not — resolved by the caller, e.g. FrameLayout). */
  readonly homeHref: string;
  /** The exercise the login modal should authenticate against. Optional,
   * defaulting to "" — see FrameLayout.tsx's own note on which routes
   * thread a real id today. */
  readonly exerciseId?: string;
}

/** The chrome-visible session shape this component renders from — either
 * the hook's own resolved state, or a local override applied the instant
 * THIS component's own login/logout action changes it (see file header). */
type DisplaySession =
  | { readonly state: "authenticated"; readonly session: FrameSession }
  | { readonly state: "unauthenticated" };

const FIELD_WRAPPER_CLASSES = "min-w-cog-0 flex-1 max-w-frame-field";

export function FrameTopBar({
  homeHref,
  exerciseId = "",
}: FrameTopBarProps): ReactElement {
  const searchInputId = useId();
  const sessionState = useFrameSession();
  const [loginOpen, setLoginOpen] = useState(false);
  const [override, setOverride] = useState<DisplaySession | null>(null);
  const [loggingOut, setLoggingOut] = useState(false);

  const effective: DisplaySession =
    override ??
    (sessionState.state === "authenticated"
      ? { state: "authenticated", session: sessionState.session }
      : { state: "unauthenticated" });
  const identity = effective.state === "authenticated" ? effective.session.character : null;
  const identityLabel = identity
    ? identity.displayName || identity.handle || identity.id
    : "";

  async function handleLogout(): Promise<void> {
    setLoggingOut(true);
    try {
      await apiLogout();
    } catch {
      // Swallow: the local session is cleared regardless below so the
      // chrome never strands the participant on a stale "logged in" chip
      // (Kite's own handleLogout takes the identical fail-open stance —
      // KiteApp.tsx's handleLogout comment explains the same rationale).
    } finally {
      clearFrameSession();
      setOverride({ state: "unauthenticated" });
      setLoggingOut(false);
    }
  }

  function handleLoginSuccess(session: FrameSession): void {
    setOverride({ state: "authenticated", session });
    setLoginOpen(false);
  }

