/**
 * StatusNotice — a prop-driven notice used at four call sites (browse empty,
 * browse error, watch unavailable, up-next empty; PLAN.md Task 5), which is
 * what justifies extracting it rather than inlining the markup four times.
 *
 * Unlike its siblings, StatusNotice takes its title/body as PROPS, not as
 * m.frame_*() keys itself — each caller owns which i18n key it passes, so
 * this component stays presentational and reusable across all four call
 * sites without hardcoding any one of them.
 *
 * `tone` maps directly to the ARIA role: "status" (loading/empty — a11y
 * "polite" region) vs "alert" (error — a11y "assertive" region). DESIGN.md
 * §9 / §7.
 *
 * The optional `action` (Retry, on the error call site) is the ONLY
 * consumer of `frame-accent-solid` / `frame-accent-ink` in this package
 * (PLAN.md Task 5, tests/tokens/frameTokens.test.ts T-b3) — those two
 * tokens are declared "ships now" specifically because this button is a
 * real, tested consumer (DESIGN.md §10).
 *
 * Heading level: an optional `headingLevel` prop picks the element `title`
 * renders as. Kept intentionally simple — a two-member union ("h1" | "h2")
 * defaulting to a plain "p" — rather than a generic "as" escape hatch,
 * because there are exactly two shapes callers need: BrowseRoute already
 * owns its own page <h1> ("Videos") elsewhere, so its empty/error notices
 * pass no `headingLevel` (title renders as a plain paragraph); WatchRoute
 * has no page heading of its own, so its notice's title literally IS that
 * route's only h1 (DESIGN.md §9 "exactly one h1 per route") and passes
 * `headingLevel="h1"`.
 */

import { FOCUS_RING } from "../lib/frameClasses";

interface StatusNoticeAction {
  label: string;
  onClick: () => void;
}

export interface StatusNoticeProps {
  tone: "status" | "alert";
  title: string;
  body: string;
  action?: StatusNoticeAction;
  headingLevel?: "h1" | "h2";
}

export default function StatusNotice({
  tone,
  title,
  body,
  action,
  headingLevel,
}: StatusNoticeProps) {
  const TitleTag = headingLevel ?? "p";
  return (
    <div
      role={tone}
      // className value kept off the `className=` line deliberately:
      // tests/rtl-logical-props.test.ts's PHYSICAL regex has no trailing
      // word boundary on `rounded-l`/`rounded-r`, so it substring-matches
      // "rounded-lg" (a size, not an RTL-unsafe physical-side radius) as a
      // false positive when both appear on one line. Not a physical
      // direction class — `rounded-lg` is size-only, no `-l-`/`-r-` side.
      className={
        "rounded-lg border border-frame-border bg-frame-surface p-cog-5 text-center"
      }
    >
      <TitleTag className="font-semibold text-frame-text">{title}</TitleTag>
      <p className="text-body-sm text-frame-text2">{body}</p>
      {action ? (
        <button
          type="button"
          onClick={action.onClick}
          // Focus ring: outline-based, not box-shadow — a deliberate
          // divergence from Commons' `focus:ring-2 focus:ring-cog-focus`
          // (box-shadow-based). design.md §0 requires an idle-state-visible
          // outline, and Frame (a simulated external site) owns its own
          // focus color the way Kite's own chrome does (PLAN.md Notes §4 C10).
          className={`min-h-btn rounded-pill bg-frame-accent-solid px-cog-4 font-semibold text-frame-accent-ink ${FOCUS_RING}`}
        >
          {action.label}
        </button>
      ) : null}
    </div>
  );
}


