/**
 * VideoGrid — the browse-page video card grid (DESIGN.md §3, §6, §8;
 * PLAN.md Task 5; #2953).
 *
 * `role="list"` is explicit because a styled `<ul>` (no bullets, grid
 * layout) loses its implicit list semantics in some browsers/AT
 * combinations; `aria-label` interpolates the live card count via the ICU
 * `frame_grid_label({count})` key so assistive tech hears "N videos".
 *
 * Each card's href is supplied by the caller as `hrefFor(id)`, not a bare
 * `base` string + a hardcoded route shape: `BrowseRoute` (a later slice)
 * passes `(id) => watchHrefFor(base, id)` (src/lib/framePaths.ts), so this
 * component stays ignorant of the URL shape and the caller owns exactly
 * one seam for building it — the cleaner contract than threading `base`
 * through as a second prop and hardcoding the `/watch?v=` shape here too.
 *
 * `now` is the scenario-clock "now" (epoch ms), resolved ONCE by the
 * caller (`src/lib/scenarioClock.ts::scenarioNow()`) and threaded through
 * unchanged to every card — the same "caller resolves, component stays
 * ignorant" shape as `hrefFor` above, and the reason every card on one
 * page agrees on the same relative-time reference instant.
 *
 * #2953: per-card rendering now delegates to `FrameVideoCard` (thumb +
 * duration badge + avatar + title + view count + scenario-relative publish
 * time + overflow menu) instead of the plain thumb/title/by-line markup
 * this component used to inline directly — that inline markup is the
 * "stub this slice was meant to replace," deleted rather than kept
 * alongside the real component.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { FrameVideoCard } from "./FrameVideoCard";
import type { FrameVideo } from "../lib/videoSource";
import { GRID_CLASSES } from "../lib/frameClasses";

export interface VideoGridProps {
  readonly cards: readonly FrameVideo[];
  /** Builds a card's watch href from its id — see the file header. */
  readonly hrefFor: (id: string) => string;
  /** Scenario-clock "now" (epoch ms) — see the file header. */
  readonly now: number;
}

// T18-adjacent invariant: this package's T-BP2/T18 precedent
// (frontends/studio-mfe/src/tools/__tests__/ContentCreator
// .adaptiveLayout.test.tsx:351) is why the responsive column classes below
// are asserted via a rendered className check in
// tests/components/VideoGrid.test.tsx rather than only through accessible
// queries — the invariant genuinely IS the class (which breakpoint a
// column count activates at), and jsdom has no layout engine to prove it
// any other way. `GRID_CLASSES` itself now lives in src/lib/frameClasses.ts,
// shared with BrowseRoute's loading-skeleton grid (see that file's header).

export function VideoGrid({ cards, hrefFor, now }: VideoGridProps): ReactElement {
  return (
    // NOT redundant despite the eslint-disable below: Safari/VoiceOver
    // strips a styled <ul>'s implicit list role once its bullets are
    // removed by the grid layout, so this explicit role restores the
    // semantics CSS otherwise removes. Precedent:
    // studio-mfe/src/components/character/CharacterSetGallery.tsx:275.
    // eslint-disable-next-line jsx-a11y/no-redundant-roles
    <ul
      role="list"
      aria-label={m.frame_grid_label({ count: cards.length })}
      className={GRID_CLASSES}
    >
      {cards.map((card) => (
        <li key={card.id} className="min-w-cog-0">
          <FrameVideoCard video={card} href={hrefFor(card.id)} now={now} />
        </li>
      ))}
    </ul>
  );
}



